// ?Add_Prototype_Impl@AssetRegistry@@QAEXPAX@Z
// partial score=0.94 date=2026-09-27
// ?Add_Prototype_Impl@AssetRegistry@@QAEXPAX@Z
// cl: /DNDEBUG /MD /EHsc /O2 /Ob2 /D_STLP_USE_STATIC_LIB
// stlport
//
// The registry insertion the free ?Add_Prototype@@YAXPAX@Z (Add_Prototype.cpp)
// forwards to once g_theAssetRegistry is non-null. Retail 0x009EF1A0, 224
// bytes, three exits and its own SEH frame: the `proto == 0` early return,
// the `key == 0` return and the tail. The 1102-byte body Ghidra starts at
// 0x009EF280 is a DIFFERENT function -- the matched
// ?bfmeGo1024E@BfmeE1024@@QAEXXZ at 0x009EB8D0 calls it directly, and
// symbols.csv pins ?bfmeReg1024@BfmeP1024@@QAEXPAVBfmeE1024@@@Z there -- so
// this body stops at its own `ret 4`.
//
// The layout is the registry's, as the landed constructor
// ??0Gen_dtor_009eb9e0@@QAE@XZ size-checks and Find_Asset.cpp uses: the
// TEA lock at +0x2C, the hash_map<int, Gen_t_009f14c0_p12cd> at +0x44, the
// iterator into it at +0x58 and the name-key generator at +0x1F0. The map
// type is the constructor's, which is also what makes the out-of-line find
// 0x009EE6D0 and begin 0x009EE0F0 resolve (bfmeInvoke already calls the
// former on the same typedef).
//
// The asset is the one Find_Asset.cpp's AssetReference counts: it bumps the
// sixteen-bit word at +4 without a null test, and this body bumps the same
// word. Slot 0 is the name lookup nameToLowercaseKey is handed, and the
// dword at +8 receives the name key this body just computed.
//
// PARTIAL, 210 of 224 bytes. Everything matches modulo relocation slots --
// prologue, the `sub esp,0x10` frame, all three exits, the `mov [esp+0x24],0`
// unwind-state store, the reused inbound argument slot for `key`, both hidden
// iterator return slots, and retail's own unwind map (one state, funclet
// `lea ecx,[ebp-0x1c]; jmp <guard dtor>`) -- and the residue is 14 bytes of
// pure register naming: retail keeps the lock address in EBX and the map
// address in EBP, this build keeps them in EBP and EBX. The save POSITIONS
// are already retail's (lock saved in the prologue, map saved at +0x74), so
// only the two register names swap. Measured insensitive to: local
// definition order (lock/map/key/iterator, with and without an initialiser
// split), the guard spelling (raw pointer, int, reference, extra member,
// nested block), the map spelling (member, &member, (T *)((char *)this+0x44),
// declared before or after the guard), prefix vs postfix refcount, a
// NameKeyType key, a merged `if (it._M_cur == 0) { ... }` tail, a null-first
// `if (proto != 0) { ... }` wrap, explicit enter/leave with no guard (that
// drops the SEH prologue entirely), _ReadWriteBarrier/_WriteBarrier
// placements, and the /G5 /G6 /G7 /GB /Ob1 /Os /Ot /Op /Oi /O1 flag sweep.
// blocker=regalloc/ebx-ebp-mirror

#define _STLP_NO_EXCEPTIONS 1
#define _STLP_USE_STATIC_LIB 1
#include <hash_map>

class BfmeLockTEA
{
public:
	char m_data[0x18];
};

extern "C" __declspec(dllimport) void __stdcall bfmeEnterTEA(BfmeLockTEA *lock);
extern "C" __declspec(dllimport) void __stdcall bfmeLeaveTEA(BfmeLockTEA *lock);

class CriticalSectionLock
{
public:
	explicit CriticalSectionLock(BfmeLockTEA *lock) : m_lock(lock)
	{
		bfmeEnterTEA(m_lock);
	}
	~CriticalSectionLock()
	{
		bfmeLeaveTEA(m_lock);
	}

	BfmeLockTEA *m_lock;
};

enum NameKeyType
{
	NAMEKEY_INVALID = 0,
	FORCE_NAMEKEYTYPE_LONG = 0x7fffffff
};

class NameKeyGenerator
{
public:
	NameKeyType nameToLowercaseKey(const char *name);
};

class CountedAsset
{
public:
	virtual const char *Get_Name();

	unsigned short m_refcount;
	unsigned short m_unmodelled_006;
	unsigned int m_name_key;
};

struct Gen_t_009f14c0_p12cd
{
	void *m_asset;
	int a[2];
	Gen_t_009f14c0_p12cd();
	Gen_t_009f14c0_p12cd(const Gen_t_009f14c0_p12cd &);
	~Gen_t_009f14c0_p12cd();
	Gen_t_009f14c0_p12cd &operator=(const Gen_t_009f14c0_p12cd &);
};

typedef _STL::hash_map<int, Gen_t_009f14c0_p12cd> GenAssetHash;

class AssetRegistry
{
public:
	void Add_Prototype_Impl(void *proto);

private:
	unsigned char m_unmodelled_000[0x2c];
	BfmeLockTEA m_lock;
	GenAssetHash m_map44;
	GenAssetHash::iterator m_iterator58;
	unsigned char m_unmodelled_060[0x190];
	NameKeyGenerator *m_hash_context;
};

void AssetRegistry::Add_Prototype_Impl(void *proto)
{
	if (proto == 0)
		return;

	CriticalSectionLock lock(&m_lock);
	int key = (int)m_hash_context->nameToLowercaseKey(
		((CountedAsset *)proto)->Get_Name());
	if (key == 0)
		return;

	GenAssetHash::iterator it = m_map44.find(key);
	if (it._M_cur != 0)
		return;

	++((CountedAsset *)proto)->m_refcount;
	m_map44[key].m_asset = proto;
	((CountedAsset *)proto)->m_name_key = (unsigned int)key;
	m_iterator58 = m_map44.begin();
}
